            tokens.append(('STR_TEXT', text[start:i]))
        elif c.isspace():
            start = i
            while i < n and text[i].isspace(): i += 1
            tokens.append(('SPACE', text[start:i]))
        elif c == '#' and not is_double_quote:
            start = i
            while i < n and text[i] != '\n': i += 1
            tokens.append(('COMMENT', text[start:i]))
        elif c == "'" and not is_double_quote:
            start = i
            i += 1
            while i < n and text[i] != "'": i += 1
            if i < n: i += 1
            tokens.append(('STR_S', text[start:i]))
        elif c == '"' and not is_double_quote:
            start = i + 1
            i += 1
            inner = ""
            while i < n and text[i] != '"':
                if text[i] == '\\':
                    inner += text[i:i+2]
                    i += 2
                else:
                    inner += text[i]
                    i += 1
            if i < n: i += 1
            tokens.append(('STR_D', tokenize(inner, True)))
        elif c == '\\':
            tokens.append(('WORD', text[i:i+2]))
            i += 2
        elif c == '$':
            if i+1 < n and text[i+1] == '(':
                start = i + 2
                i += 2
                depth = 1
                inner = ""
                while i < n and depth > 0:
                    if text[i] == '\\':
                        inner += text[i:i+2]
                        i += 2
                    elif text[i] == '(': depth += 1; inner += text[i]; i += 1
                    elif text[i] == ')':
                        depth -= 1
                        if depth > 0: inner += text[i]
                        i += 1
                    elif text[i] == "'":
                        inner += text[i]
                        i += 1
                        while i < n and text[i] != "'":
                            inner += text[i]
                            i += 1
                        if i < n: inner += text[i]; i += 1
                    elif text[i] == '"':
                        inner += text[i]
                        i += 1
                        while i < n and text[i] != '"':
                            if text[i] == '\\': inner += text[i:i+2]; i += 2
                            else: inner += text[i]; i += 1
                        if i < n: inner += text[i]; i += 1
                    else:
                        inner += text[i]
                        i += 1
                tokens.append(('CMD_SUB', tokenize(inner)))
            elif i+1 < n and text[i+1] == '{':
                start = i
                i += 2
                while i < n and text[i] != '}': i += 1
                if i < n: i += 1
                tokens.append(('VAR', text[start:i]))
            else:
                m = re.match(r'\$([a-zA-Z_][a-zA-Z0-9_]*|[?*@#$$!0-9])', text[i:])
                if m:
                    tokens.append(('VAR', m.group(0)))
                    i += len(m.group(0))
                else:
                    if is_double_quote:
                        tokens.append(('STR_TEXT', '$'))
                    else:
                        tokens.append(('WORD', '$'))
                    i += 1
        elif c == '`':
            start = i + 1
            i += 1
            inner = ""
            while i < n and text[i] != '`':
                if text[i] == '\\': inner += text[i:i+2]; i += 2
                else: inner += text[i]; i += 1
            if i < n: i += 1
