{"command":"cat << 'EOF' > formatter.py
import re

C_CMD = "\033[0;38;2;192;0;128m"
C_VAR = "\033[0;38;2;63;127;207m"
C_STR_D = "\033[0;38;2;255;0;0m"
C_STR_S = "\033[0;38;2;255;204;85m"
C_KW = "\033[0;1m"
C_LHS = "\033[0;38;2;0;127;255m"
C_COMMENT = "\033[0;1;3;38;2;120;144;96m"
C_MAGENTA = "\033[0;38;2;192;0;192m"
C_RESET = "\033[m"
C_SUGGEST = "\033[0;42m"

KEYWORDS = {"if", "then", "elif", "else", "fi", "case", "in", "esac", "while", "until", "for", "do", "done", "function", "local", "export", "readonly", "declare", "typeset"}
EXCEPTIONS = {"$?", "$$", "$!", "$#"}

def format_tokens(tokens, is_syntax, is_suggest, is_double_quote=False):
    # group tokens by word
    words = []
    current_word = []
    for tok in tokens:
        if tok[0] == 'SPACE' and not is_double_quote:
            if current_word:
                words.append(current_word)
                current_word = []
            words.append([tok])
        else:
            current_word.append(tok)
    if current_word:
        words.append(current_word)

    out = ""
    is_first_word = True
    in_assignment = False
    is_case_cond = False
    in_dbl_bracket = False

    for word in words:
        if not word: continue
        if word[0][0] == 'SPACE':
            out += word[0][1]
            continue

        # check if word is assignment
        word_is_assignment = False
        if is_first_word and word[0][0] == 'WORD':
            m = re.match(r'^([a-zA-Z_][a-zA-Z0-9_]*)=(.*)', word[0][1])
            if m:
                word_is_assignment = True

        # check if keyword
        is_keyword = is_first_word and word[0][0] == 'WORD' and word[0][1] in KEYWORDS

        if is_keyword:
            if is_syntax:
                out += C_KW + word[0][1] + C_RESET
            else:
                out += word[0][1]
            if word[0][1] in ('case',):
                is_case_cond = True
            elif word[0][1] in ('in',):
                is_case_cond = False
            # process rest of the word if any (unlikely for keywords)
            for tok in word[1:]:
                out += format_token(tok, is_syntax, is_suggest, is_double_quote, False, in_dbl_bracket)
            # is_first_word might change based on keyword, usually remains True for 'if', 'while'
            if word[0][1] in ('in', 'do', 'then', 'else'):
                is_first_word = True
            continue

        if word[0][0] == 'OP':
            if word[0][1] == '[[':
                in_dbl_bracket = True
            elif word[0][1] == ']]':
                in_dbl_bracket = False

            if word[0][1] in (';', '|', '&&', '||', '\n', '&'):
                is_first_word = True

            if is_syntax and in_dbl_bracket: # [[ ... ]] gets magenta
                out += C_MAGENTA + word[0][1] + C_RESET
            elif is_syntax and word[0][1] in ('[[', ']]', '=='):
                out += C_MAGENTA + word[0][1] + C_RESET
            else:
                if is_syntax and word[0][1] == '[' and is_first_word:
                    out += C_CMD + word[0][1] + C_RESET
                else:
                    out += word[0][1]

            for tok in word[1:]:
                out += format_token(tok, is_syntax, is_suggest, is_double_quote, False, in_dbl_bracket)
            continue

        if word_is_assignment:
            m = re.match(r'^([a-zA-Z_][a-zA-Z0-9_]*)=(.*)', word[0][1])
            lhs = m.group(1)
            rest = m.group(2)
            if is_syntax:
                out += C_LHS + lhs + C_RESET + '=' + rest
            else:
                out += word[0][1]

            for tok in word[1:]:
                out += format_token(tok, is_syntax, is_suggest, is_double_quote, True, in_dbl_bracket)
            continue

        # otherwise, normal command or argument
        if is_first_word and not is_double_quote:
            is_cmd = True
            is_first_word = False
        else:
            is_cmd = False

        for i, tok in enumerate(word):
            # The first string/word in word is the command
            if i == 0 and is_cmd and is_syntax and tok[0] == 'WORD':
                out += C_CMD + tok[1] + C_RESET
            else:
                out += format_token(tok, is_syntax, is_suggest, is_double_quote, False, in_dbl_bracket or is_case_cond)

    return out

def format_token(tok, is_syntax, is_suggest, is_double_quote, is_rhs, in_special_context):
    typ, val = tok
    if typ == 'WORD':
        return val
    elif typ == 'STR_TEXT':
        return val
    elif typ == 'COMMENT':
        return C_COMMENT + val + C_RESET if is_syntax else val
    elif typ == 'STR_S':
