        else:
            return '"' + inner + '"'
    elif typ in ('VAR', 'CMD_SUB_PAREN', 'CMD_SUB_BACKTICK'):
        needs_quote = False
        if typ == 'VAR' and val in EXCEPTIONS:
            needs_quote = False
        elif is_double_quote or is_rhs or in_special_context:
            needs_quote = False
        else:
            needs_quote = True

        if typ == 'VAR':
            formatted_val = C_VAR + val + C_RESET if is_syntax else val
        elif typ == 'CMD_SUB_PAREN':
            inner_tokens = tokenize(val)
            inner_formatted = format_tokens(inner_tokens, is_syntax, is_suggest, False)
            if is_syntax:
                formatted_val = '$(' + inner_formatted + ')'
            else:
                formatted_val = '$(' + inner_formatted + ')'
        elif typ == 'CMD_SUB_BACKTICK':
            inner_tokens = tokenize(val)
            inner_formatted = format_tokens(inner_tokens, is_syntax, is_suggest, False)
            if is_syntax:
                formatted_val = '`' + inner_formatted + '`'
            else:
                formatted_val = '`' + inner_formatted + '`'

        if needs_quote and is_suggest:
            if is_syntax:
                return C_SUGGEST + '"' + C_RESET + formatted_val + C_SUGGEST + '"' + C_RESET
            else:
                return '"' + formatted_val + '"'
        else:
            return formatted_val
    return val

def process_text(text, mode):
    is_syntax = mode in ('syntax', 'syntax-suggest')
    is_suggest = mode in ('suggest', 'syntax-suggest', 'transform', 'replace')

    tokens = tokenize(text)
    out = format_tokens(tokens, is_syntax, is_suggest, False)

    if mode == 'transform' or mode == 'replace':
        ansi_escape = re.compile(r'\x1B(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])')
        out = ansi_escape.sub('', out)

    return out

def print_help():
    print("""Shellharden: The corrective bash syntax highlighter.

Usage:
	shellharden [options] [files]
	cat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
	--suggest         Output a colored diff suggesting changes.
	--syntax          Output syntax highlighting with ANSI colors.
	--syntax-suggest  Diff with syntax highlighting (default mode).
	--transform       Output suggested changes.
	--check           No output; exit with 2 if changes are suggested.
	--replace         Replace file contents with suggested changes.
	--                Don't treat further arguments as options.
	-h|--help         Show help text.
	--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md""")

def main():
    args = sys.argv[1:]
    mode = 'syntax-suggest'
    files = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--suggest': mode = 'suggest'
        elif arg == '--syntax': mode = 'syntax'
        elif arg == '--syntax-suggest': mode = 'syntax-suggest'
        elif arg == '--transform': mode = 'transform'
        elif arg == '--check': mode = 'check'
        elif arg == '--replace': mode = 'replace'
        elif arg in ('-h', '--help'):
            print_help()
            return
        elif arg == '--version':
            print("4.3.1")
            return
        elif arg == '--':
            files.extend(args[i+1:])
            break
        elif arg.startswith('--'):
            print(f"{arg}: No such option.", file=sys.stderr)
            sys.exit(3)
        elif arg.startswith('-') and arg != '-':
            print(f"{arg}: No such option.", file=sys.stderr)
            sys.exit(3)
        else:
            files.append(arg)
        i += 1

    if not files:
        if not sys.stdin.isatty():
            text = sys.stdin.read()
            if not text:
                return
        else:
            return

        res = process_text(text, mode)
        if mode == 'check':
            if res != text: sys.exit(2)
        else:
            print(res, end='')
    else:
        for f in files:
            if f == '':
                text = sys.stdin.read()
                res = process_text(text, mode)
                if mode == 'check':
                    if res != text: sys.exit(2)
                else:
                    print(res, end='')
            else:
                with open(f, 'r') as fp:
                    text = fp.read()
                res = process_text(text, mode)
                if mode == 'check':
                    if res != text: sys.exit(2)
                elif mode == 'replace':
                    with open(f, 'w') as fp:
                        fp.write(res)
                else:
                    print(res, end='')

if __name__ == '__main__':
    main()
